body.vi:
Khuôn mẫu lớp `Stack<T>` cung cấp các thao tác ngăn xếp tiêu chuẩn: `push`, `pop`, `top`, `isEmpty`, và `size`. Thay vì tự cấp phát bộ nhớ mảng động phức tạp, `Stack<T>` đóng vai trò là một container adapter (bộ điều hợp), ủy quyền (delegates) toàn bộ trách nhiệm lưu trữ và truy cập cho container bên dưới (ở đây mặc định là `std::deque<T>`).

Khi các hàm thành viên được viết bên trong định nghĩa lớp template, chúng ngầm định được xem là các khuôn mẫu hàm nội tuyến (`inline function templates`). Tuy nhiên, nếu bạn tách định nghĩa hàm ra bên ngoài phần thân lớp, mỗi hàm phải bắt đầu bằng tiêu đề khuôn mẫu `template<typename T>`, tên hàm phải được định danh tầm vực với `Stack<T>::`, và tốt nhất nên thêm từ khóa `inline` nếu nằm trong tệp tiêu đề (header file):

```cpp
template<typename T>
inline void Stack<T>::pop() {
    stack.pop_front();
}
```
Toán tử phân giải phạm vi `Stack<T>::` báo hiệu cho trình biên dịch biết rằng hàm này thuộc phạm vi của chuyên biệt hóa `Stack<T>`. Lưu ý: trong C++ hiện đại, các khuôn mẫu lớp thư viện chuẩn thường được định nghĩa hàm hoàn chỉnh ngay trong lớp để giảm sự rườm rà.

body.en:
The `Stack<T>` class template provides conventional stack operations: `push`, `pop`, `top`, `isEmpty`, and `size`. Instead of managing raw heap buffers, `Stack<T>` acts as a container adapter, delegating element storage and manipulation to its underlying member container (specifically, `std::deque<T>`).

When member functions are written inside the class template body, they are implicitly treated as inline function templates. When separating member function definitions outside the class definition, each member function must begin with `template<typename T>`, must be qualified with `Stack<T>::`, and should ideally be marked `inline` when placed in a header file:

```cpp
template<typename T>
inline void Stack<T>::pop() {
    stack.pop_front();
}
```
The scope resolution qualifier `Stack<T>::` informs the compiler that the function belongs to the scope of class `Stack<T>`. In modern standard libraries, container templates typically implement functions directly inside the class definition to maintain clarity and concise headers.

example.code:
#include <iostream>
#include <deque>
#include <cstddef>

template<typename T>
class Stack {
public:
    const T& top() const {
        return stack.front();
    }

    void push(const T& pushValue) {
        stack.push_front(pushValue);
    }

    void pop(); // defined outside the class template body

    bool isEmpty() const {
        return stack.empty();
    }

    std::size_t size() const {
        return stack.size();
    }

private:
    std::deque<T> stack;
};

template<typename T>
inline void Stack<T>::pop() {
    stack.pop_front();
}

int main() {
    Stack<double> doubleStack;
    const std::size_t doubleStackSize = 5;
    double doubleValue = 1.1;

    std::cout << "Pushing elements onto doubleStack\n";
    for (std::size_t i = 0; i < doubleStackSize; ++i) {
        doubleStack.push(doubleValue);
        std::cout << doubleValue << ' ';
        doubleValue += 1.1;
    }

    std::cout << "\n\nPopping elements from doubleStack\n";
    while (!doubleStack.isEmpty()) {
        std::cout << doubleStack.top() << ' ';
        doubleStack.pop();
    }
    std::cout << "\nStack is empty, cannot pop.\n";

    Stack<int> intStack;
    const std::size_t intStackSize = 5;
    int intValue = 1;

    std::cout << "\nPushing elements onto intStack\n";
    for (std::size_t i = 0; i < intStackSize; ++i) {
        intStack.push(intValue);
        std::cout << intValue++ << ' ';
    }

    std::cout << "\n\nPopping elements from intStack\n";
    while (!intStack.isEmpty()) {
        std::cout << intStack.top() << ' ';
        intStack.pop();
    }
    std::cout << "\nStack is empty, cannot pop.\n";

    return 0;
}

#include <iostream>
#include <string>
#include <deque>
#include <cstddef>

template<typename T>
class Stack {
public:
    const T& top() const {
        return stack.front();
    }

    void push(const T& pushValue) {
        stack.push_front(pushValue);
    }

    void pop() {
        stack.pop_front();
    }

    bool isEmpty() const {
        return stack.empty();
    }

    std::size_t size() const {
        return stack.size();
    }

private:
    std::deque<T> stack;
};

template<typename T>
void testStack(
    Stack<T>& theStack,
    const T& value,
    const T& increment,
    std::size_t size,
    const std::string& stackName
) {
    std::cout << "\nPushing elements onto " << stackName << '\n';
    T pushValue = value;

    for (std::size_t i = 0; i < size; ++i) {
        theStack.push(pushValue);
        std::cout << pushValue << ' ';
        pushValue += increment;
    }

    std::cout << "\n\nPopping elements from " << stackName << '\n';
    while (!theStack.isEmpty()) {
        std::cout << theStack.top() << ' ';
        theStack.pop();
    }

    std::cout << "\nStack is empty. Cannot pop.\n";
}

int main() {
    Stack<double> doubleStack;
    const std::size_t doubleStackSize = 5;
    testStack(doubleStack, 1.1, 1.1, doubleStackSize, "doubleStack");

    Stack<int> intStack;
    const std::size_t intStackSize = 10;
    testStack(intStack, 1, 1, intStackSize, "intStack");

    return 0;
}
